"""Contract test — audit_surface_truth.json isolation discipline.

Background
----------
``audit_dashboard/data/audit_surface_truth.json`` is a VERDICT panel
generated by ``tools/build_audit_surface_truth.py``. It carries the
single trust panel for /audit surfaces (ai-tournament.html,
ai_leaderboard.html, template major-goal JS). It currently carries::

    "_schema_note": "Generated by tools/build_audit_surface_truth.py; ..."
    "audit_surface_truth_only": True

The payload encodes VERDICT data (money-ready classes, trust hierarchy,
disputed surfaces, headline "0/9 money-ready") — never a sizing signal.
The schema contract is the ``audit_surface_truth_only: True`` gate flag
(machine-readable proxy for "this is verdict data, not sizing input").

That contract is currently a docstring — Python has no way to enforce
it. This test enforces it pre-merge so a future ``tools/consume_picks.py``
(or any *.py under ``tools/``, ``audit_trail/``, ``alpha_engine/``) that
silently re-ingests this verdict panel as a sizing source FAILS the test
instead of shipping to production.

The contract — two acceptable signals in a consumer candidate:

1. The file references the gate flag ``audit_surface_truth_only`` (the
   "this is verdict data, not sizing" proxy), OR
2. The file carries an explicit ``# allowed: audit-surface-truth
   consumer`` comment on its own line (a human-acknowledged override).

A file that reads ``audit_surface_truth.json`` and carries neither
signal is flagged as an **unguarded consumer** and the test fails.

This test mirrors ``tests/test_no_sizing_consumer.py`` (which guards
``operator_review_today.json``) and ``tests/test_no_winner_hunt_replay_consumer.py``
(which guards ``winner_hunt_replay_payload.json``) — same shape, different
gate-flag + marker.

Cron-mode fail-closed
---------------------
When ``AUDIT_SURFACE_TRUTH_CRON_MODE=1`` is set in the env, a missing
payload AFTER the build step ran becomes a ``pytest.fail()`` (not a
``pytest.skip()``). Local pytest runs (env unset) keep the
developer-friendly skip path.

See:
- ``audit_dashboard/data/audit_surface_truth.json`` for the payload +
  its ``_schema_note`` / ``audit_surface_truth_only`` fields
- ``tools/build_audit_surface_truth.py`` for the writer
- ``.github/workflows/ai-leaderboard-freshness.yml`` and
  ``.github/workflows/audit-dashboard.yml`` for current cron wiring
  (TODO: add a `Run contract tests` step mirroring the operator-review +
  winner-hunt-replay pattern — see updates/2026-06-22-operator-review-today-panel.md)
"""

from __future__ import annotations

import json
import os
import re
from pathlib import Path

import pytest

# --------------------------------------------------------------------------- #
# Configuration — keep this list narrow; only writers and self may be exempt. #
# --------------------------------------------------------------------------- #

REPO = Path(__file__).resolve().parent.parent

# Scan roots: any *.py here that reads the payload is a consumer candidate.
SCAN_ROOTS = [
    REPO / "tools",
    REPO / "audit_trail",
    REPO / "alpha_engine",
]

# Files exempt from the scan. Two legitimate categories today:
#   1. The writer (build script — it WRITES the payload, never reads it back
#      as a sizing source, but the filename literal appears in source as
#      PRIOR_PAYLOAD_PATH/OUT_PAYLOAD_PATH).
#   2. The test file itself (it necessarily mentions both the filename and
#      the gate-flag in source).
EXEMPT_BASENAMES = {
    "build_audit_surface_truth.py",             # writer — produces the payload
    "test_no_audit_surface_truth_consumer.py",  # self — this file
}

# Cache & generated artifacts we never want to scan.
EXEMPT_SUFFIX_PARTS = ("__pycache__", ".pyc")

# Contract signals.
SIDECAR_FILENAME = "audit_surface_truth.json"
GUARD_FLAG = "audit_surface_truth_only"
ALLOW_COMMENT_RE = re.compile(
    r"#\s*allowed:\s*audit-surface-truth\s+consumer\b"
)
SIDECAR_CONTRACT_KEYS_REQUIRED = ("_schema_note", "audit_surface_truth_only")

# Cron-mode gate: when/if the workflow's "Run contract tests" step sets
# AUDIT_SURFACE_TRUTH_CRON_MODE=1 in its env block, a missing payload
# AFTER the build step ran is a HARD regression. The inline cron branch
# converts the developer-friendly pytest.skip() into a hard pytest.fail()
# so the workflow contract step stops BEFORE the commit step can run.
# Local pytest runs (env unset) keep the skip-friendly default so a
# developer without the build can still run this contract test.
CRON_MODE = os.environ.get("AUDIT_SURFACE_TRUTH_CRON_MODE", "") == "1"


# --------------------------------------------------------------------------- #
# Detection helpers                                                          #
# --------------------------------------------------------------------------- #

def _consumes_sidecar(content: str) -> bool:
    """True if the file opens AND reads audit_surface_truth.json."""
    if SIDECAR_FILENAME not in content:
        return False
    intent_patterns = (
        "open(", "read_text", "read_bytes",
        "json.load", "json.loads",
        "yaml.safe_load", "yaml.load",
        "tomllib.load",
        ".load(", ".loads(",
    )
    return any(pat in content for pat in intent_patterns)


def _carries_guard(content: str) -> bool:
    """True if the file references the audit_surface_truth_only gate flag."""
    return GUARD_FLAG in content


def _carries_allow_marker(content: str) -> bool:
    """True if the file carries an explicit `# allowed: audit-surface-truth
    consumer` marker."""
    return bool(ALLOW_COMMENT_RE.search(content))


def _is_exempt(path: Path) -> bool:
    if path.name in EXEMPT_BASENAMES:
        return True
    if any(part in EXEMPT_SUFFIX_PARTS for part in path.parts):
        return True
    return False


def _scan_files():
    """Yield every scanned-eligible *.py under SCAN_ROOTS."""
    for root in SCAN_ROOTS:
        if not root.exists():
            continue
        for path in root.rglob("*.py"):
            if not path.is_file():
                continue
            if _is_exempt(path):
                continue
            yield path


# --------------------------------------------------------------------------- #
# Pytest test functions                                                      #
# --------------------------------------------------------------------------- #

def test_no_unguarded_consumer_in_scan_roots():
    """ANY *.py under tools/ + audit_trail/ + alpha_engine/ that opens
    audit_surface_truth.json MUST also reference the
    audit_surface_truth_only gate flag OR carry the explicit
    ``# allowed: audit-surface-truth consumer`` marker on its own line.
    Otherwise it is an UNGUARDED consumer and the test fails."""
    violations: list[str] = []

    for path in _scan_files():
        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue

        if not _consumes_sidecar(content):
            continue

        if _carries_allow_marker(content):
            continue

        if _carries_guard(content):
            continue

        violations.append(path.relative_to(REPO).as_posix())

    assert not violations, (
        "Unguarded consumers of audit_surface_truth.json detected. "
        "Every *.py that opens the sidecar under {tools/, audit_trail/, "
        "alpha_engine/} must EITHER reference the `audit_surface_truth_only` "
        "gate-flag string (anywhere in the file) OR carry a line reading "
        "exactly `# allowed: audit-surface-truth consumer` (human-acknowledged "
        "override). Either add the guard reference, or add the override "
        "comment, or — if the read is no longer needed — remove the read. "
        f"Violations: {violations}"
    )


def test_sidecar_payload_carries_required_contract_keys():
    """Mirror check on the payload itself: must carry `_schema_note` AND
    `audit_surface_truth_only` fields — without these, the contract is
    not enforceable on consumers."""
    sidecar_path = REPO / "audit_dashboard" / "data" / SIDECAR_FILENAME

    if not sidecar_path.exists():
        if CRON_MODE:
            pytest.fail(
                f"HARD REGRESSION: {sidecar_path.relative_to(REPO).as_posix()} "
                "is missing AFTER the build_audit_surface_truth step ran "
                "(AUDIT_SURFACE_TRUTH_CRON_MODE=1). Possible causes: "
                "build script (tools/build_audit_surface_truth.py) "
                "failed silently to write the payload, or the contract "
                "step is running out of order. Investigate before re-running."
            )
        pytest.skip(
            f"{sidecar_path.relative_to(REPO).as_posix()} not yet produced; "
            "the audit-dashboard hourly cron will land it."
        )

    payload = json.loads(sidecar_path.read_text(encoding="utf-8"))

    missing = [k for k in SIDECAR_CONTRACT_KEYS_REQUIRED if k not in payload]
    assert not missing, (
        f"{sidecar_path.relative_to(REPO).as_posix()} is missing required "
        f"contract keys: {missing}. Both `_schema_note` and "
        "`audit_surface_truth_only` are required — the test above would "
        "have nothing to verify against."
    )

    assert payload["audit_surface_truth_only"] is True, (
        "audit_surface_truth_only must be a strict boolean True; got "
        f"{payload['audit_surface_truth_only']!r} instead."
    )


def test_exempt_set_includes_writer_and_self():
    """Sanity guard: the EXEMPT_BASENAMES table must include the writer
    and the test file itself — otherwise the writer's path literal would
    false-positive the main test, or this test would flag itself."""
    today = REPO / "tests" / "test_no_audit_surface_truth_consumer.py"
    writer = REPO / "tools" / "build_audit_surface_truth.py"

    assert today.name in EXEMPT_BASENAMES, (
        "EXEMPT_BASENAMES must contain the test file's own name to avoid a "
        "self-flagged violation on every run."
    )
    assert writer.name in EXEMPT_BASENAMES, (
        "EXEMPT_BASENAMES must contain "
        f"{writer.name!r} (the audit_surface_truth payload's build script). "
        "Either add the writer to EXEMPT_BASENAMES, or — if the writer is "
        "being retired — delete this assertion."
    )
